async function createTemporaryReferee(){const name=newReferee.value.name.trim(),phone=newReferee.value.phone.replace(/\D/g,''),reason=newReferee.value.reason.trim();if(name.length<2)return ElMessage.warning('请填写裁判姓名');if(!/^1[3-9]\d{9}$/.test(phone))return ElMessage.warning('请填写正确的手机号');if(reason.length<4)return ElMessage.warning('请填写组委会添加原因');saving.value=true;try{const result=await callFunction('tournamentRegistrationFlow',{action:'createTemporaryRefereeClaim',tournamentId:selectedTournamentId.value,name,phone,reason,previewMode});if(!result?.success)throw new Error(result?.message||result?.error||'添加失败');inviteTarget.value={_id:result.data?.refereeId,name,phone,temporaryReferee:true};inviteMode.value='temporary_no_certificate';inviteQrCode.value=result.data?.qrCodeUrl||'';newReferee.value={name:'',phone:'',reason:''};addDialog.value=false;inviteDialog.value=true;await load();ElMessage.success('临时裁判已添加，认领通知已进入发送队列')}catch(error){ElMessage.error(error.message||'添加失败')}finally{saving.value=false}}
