async function addSyntheticCandidate(candidate){if(addedSyntheticKeys.value.has(candidate.key))return;addingSyntheticKey.value=candidate.key;try{await addRecord('referees',{tournamentId:selectedTournamentId.value,name:candidate.name,realName:candidate.name,avatarUrl:candidate.avatarUrl,level:candidate.level,qualification:candidate.qualification,status:'test',auditStatus:'not_bound',availabilityStatus:'available',refereeGroupId:candidate.refereeGroupId,refereeGroupName:candidate.refereeGroupName,groupRole:candidate.groupRole,groupRoleLabel:candidate.groupRoleLabel,synthetic:true,syntheticDatasetId,syntheticKey:candidate.key,source:'ai_candidate_pool',canLogin:false,canOperate:false,notificationDisabled:true});await load();ElMessage.success(`${candidate.name}已加入名单，可以直接用于排班测试`)}catch(error){ElMessage.error(error.message||'添加模拟裁判失败')}finally{addingSyntheticKey.value=''}}
function friendlyInviteError(error){const message=String(error?.message||error||'');if(/collection.+not exists|Db or Table not exist|ResourceNotFound|DATABASE_COLLECTION_NOT_EXIST/i.test(message))return '裁判邀请功能正在初始化，请刷新页面后重试';if(/permission|auth|unauthorized/i.test(message))return '当前账号没有创建裁判邀请的权限';return '裁判邀请生成失败，请稍后重试'}
async function openRefereeInvite(referee=null){if(!selectedTournamentId.value)return ElMessage.warning('请先选择赛事');saving.value=true;inviteTarget.value=referee;try{const result=await callFunction('tournamentRegistrationFlow',{action:'createRefereeFollowInvite',tournamentId:selectedTournamentId.value,targetRefereeId:referee?._id||'',previewMode});if(!result?.success)throw new Error(result?.message||result?.error||'裁判关注二维码生成失败');inviteQrCode.value=result.data?.qrCodeUrl||'';inviteMode.value=result.data?.claimMode||'';if(!inviteQrCode.value)throw new Error('服务号关注二维码暂不可用');inviteDialog.value=true}catch(error){ElMessage.error(friendlyInviteError(error))}finally{saving.value=false}}
function exportList() { ElMessage.info('导出名单已准备，正式导出将按当前赛事与筛选范围生成') }
onMounted(load)
</script>

